SELECT USER(), @@hostname, @@port;

CREATE DATABASE shopping_db;

USE shopping_db;
SELECT COUNT(*) FROM customer_data;

SELECT * FROM customer_data LIMIT 10;

-- What is the total revenue generated by male vs female customers?
SELECT gender,SUM(purchase_amount) as total_revenue
FROM customer_data
GROUP BY gender;

-- Which customer used a discount but still spent more than the average purchase amount?
SELECT customer_id,purchase_amount 
FROM customer_data
WHERE discount_applied = 'Yes'
AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer_data);

-- Which are the top five products with the highest average review rating?
SELECT item_purchased,ROUND(AVG(review_rating),2) AS average_rating 
FROM customer_data
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;

-- Compare the average purchase amounts between standard and express shipping
SELECT ROUND(AVG(purchase_amount),2),shipping_type
FROM customer_data
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type

-- Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers


SELECT
subscription_status,
COUNT(customer_id) AS total_customer,
ROUND(AVG(purchase_amount), 2) AS average_spend,
SUM(purchase_amount) AS total_revenue
FROM shopping_db.customer_data
GROUP BY subscription_status;

-- Which five products have the highest percentage of purchases with discount applied?
SELECT item_purchased,
ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes'THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
from customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC
limit 5;

-- Segment customers into new, returming and loyal based on their total number of previous purchase and show the count of each segment
with customer_type AS(
SELECT customer_id,previous_purchases,
CASE
    WHEN previous_purchases = '1' THEN 'New'
    WHEN previous_purchases BETWEEN 1 and 10 THEN 'RETURNING'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer_data
)
SELECT customer_segment,COUNT(*) AS num_of_customers FROM customer_type
GROUP BY customer_segment;


-- What are the top 3 most purchased products within each category?
WITH item_count AS (
SELECT item_purchased,category,
COUNT(customer_id) AS total_order,
ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC )AS item_rank
FROM customer_data
GROUP BY category,item_purchased
)
SELECT item_purchased,category,total_order,item_rank
FROM item_count
WHERE item_rank<=3;

-- Are customers who are repeat buyers(more than 5 previous purchases) are likely to subscribe?
SELECT subscription_status,
COUNT(customer_id) AS repeat_buyers
FROM customer_data
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- What is the total contribution of each age group?

SELECT age_group,
SUM(purchase_amount) AS total_revenue
FROM customer_data
GROUP BY age_group
ORDER BY total_revenue DESC;



